"""AstroHealth - Astronaut Health Monitoring (NASA Hackathon prototype)
Run:  pip install -r requirements.txt  &amp;&amp;  python app.py
Open: <a href="http://127.0.0.1:5000" target="_blank" rel="noopener noreferrer" title="http://127.0.0.1:5000" class="fai-ChatInputEntity__text ___6erqso0 fyind8e f1tx3yz7 f1deo86v f1eh06m1 f1iescvh">http://127.0.0.1:5000</a>
NOTE: Prototype only. Medication/protocol output = suggestions for flight-surgeon review.
"""
import random, threading, time
from collections import deque
from flask import Flask, jsonify, request, render_template

app = Flask(__name__)

ASTRONAUTS = {
    1: {"name": "Cdr. Sara Hassan", "role": "Commander", "base_hr": 62},
    2: {"name": "Dr. Omar Nabil", "role": "Flight Surgeon", "base_hr": 66},
    3: {"name": "Eng. Laila Fathy", "role": "Engineer", "base_hr": 70},
    4: {"name": "Pilot Karim Adel", "role": "Pilot", "base_hr": 60},
}
MEDS = [  # daily schedule (example only)
    {"name": "Vitamin D", "time": "08:00"},
    {"name": "Calcium + bone support", "time": "13:00"},
    {"name": "Omega-3", "time": "20:00"},
]

# ---- shared state ----
MODE = {"value": "space"}            # "space" | "earth"
STATE, HISTORY, COG = {}, {}, {}
LOCK = threading.Lock()
SIM = {"minute": 0}                  # simulated clock: each tick = 10 sim minutes


def environment(mode):
    if mode == "earth":
        return {"mode": "earth", "gravity_g": 1.0, "cabin_pressure_kpa": 101.3,
                "lighting": "Circadian 16h day / 8h night (blue-enriched day light)",
                "radiation_shield": "Earth-like (simulated magnetosphere)",
                "artificial_gravity": "ON - centrifuge/loading suit"}
    return {"mode": "space", "gravity_g": 0.0, "cabin_pressure_kpa": 70.0,
            "lighting": "Station default (16 sunrises/day)",
            "radiation_shield": "Hull only",
            "artificial_gravity": "OFF - microgravity"}


def init_state():
    for aid, a in ASTRONAUTS.items():
        STATE[aid] = dict(hr=a["base_hr"], sys=118, dia=76, spo2=97.0, temp=36.7,
                          radiation=25.0, hydration=65.0, stage="Awake",
                          sleep_h=0.0, exercise_min=0.0, ex_left=0, fatigue=10.0)
        HISTORY[aid] = deque(maxlen=120)
        COG[aid] = {"status": "No test yet", "avg_rt": None, "miss_pct": None, "ts": None}


def sleep_stage(minute):
    hour = (minute / 60) % 24
    if not (hour &gt;= 23 or hour &lt; 7):
        return "Awake"
    m = minute % 90                  # 90-min sleep cycle
    return "Light" if m &lt; 10 else "Deep" if m &lt; 40 else "Light" if m &lt; 65 else "REM"


def tick():
    SIM["minute"] += 10
    minute, mode = SIM["minute"], MODE["value"]
    earth = mode == "earth"
    if minute % 1440 == 0:           # new day
        for s in STATE.values():
            s["sleep_h"], s["exercise_min"] = 0.0, 0.0
    for aid, a in ASTRONAUTS.items():
        s = STATE[aid]
        s["stage"] = sleep_stage(minute)
        if s["stage"] == "Awake" and s["ex_left"] == 0 and random.random() &lt; 0.06:
            s["ex_left"] = 3         # 30 min workout
        exercising = s["ex_left"] &gt; 0
        if exercising:
            s["ex_left"] -= 1
            s["exercise_min"] += 10
        if s["stage"] != "Awake":
            s["sleep_h"] += 10 / 60
        # targets depend on environment
        hr_t = a["base_hr"] + (0 if earth else 8)
        hr_t = 125 if exercising else (hr_t - 10 if s["stage"] != "Awake" else hr_t)
        spo2_t = 97.5 if earth else 96.0
        rad_t = 0.3 if earth else 28.0
        hyd_t = 68 if earth else 58
        temp_t = 36.7 if earth else 37.0
        k = 0.25
        s["hr"] += (hr_t - s["hr"]) * k + random.gauss(0, 1.5)
        s["sys"] += ((118 if earth else 126) - s["sys"]) * 0.2 + random.gauss(0, 1.5) + (10 if exercising else 0) * 0.2
        s["dia"] += ((76 if earth else 80) - s["dia"]) * 0.2 + random.gauss(0, 1)
        s["spo2"] += (spo2_t - s["spo2"]) * k + random.gauss(0, 0.4)
        s["temp"] += (temp_t - s["temp"]) * k + random.gauss(0, 0.05)
        s["radiation"] = max(0.1, s["radiation"] + (rad_t - s["radiation"]) * 0.3 + random.gauss(0, 1.5))
        s["hydration"] += (hyd_t - s["hydration"]) * 0.1 + random.gauss(0, 0.8) - (0.6 if exercising else 0)
        s["spo2"] = min(100, s["spo2"]); s["hydration"] = min(100, s["hydration"])
        # fatigue index 0-100: low SpO2, high HR, low hydration, short sleep
        f = (max(0, 96 - s["spo2"]) * 8 + max(0, s["hr"] - 100) * 0.4
             + max(0, 60 - s["hydration"]) * 1.2 + max(0, 7 - s["sleep_h"]) * (3 if s["stage"] == "Awake" else 0))
        s["fatigue"] = round(min(100, 10 + f), 1)
        HISTORY[aid].append({"t": minute, **{k_: round(s[k_], 1) for k_ in
                             ("hr", "sys", "dia", "spo2", "temp", "radiation", "hydration", "fatigue")}})


def sim_loop():
    while True:
        with LOCK:
            tick()
        time.sleep(2)


def alerts_for(s):
    out = []
    if s["spo2"] &lt; 94: out.append(("warning", "SpO2 low -&gt; risk of muscle fatigue"))
    if s["spo2"] &lt; 90: out.append(("critical", "SpO2 critical (&lt;90%)"))
    if s["hr"] &gt; 130 and s["ex_left"] == 0: out.append(("warning", "Resting HR high"))
    if s["sys"] &gt; 140 or s["dia"] &gt; 90: out.append(("warning", "Blood pressure high"))
    if s["temp"] &gt; 37.8: out.append(("warning", "Elevated temperature"))
    if s["radiation"] &gt; 40: out.append(("critical", "Radiation level high - move to shielded area"))
    if s["hydration"] &lt; 50: out.append(("warning", "Low hydration"))
    if s["fatigue"] &gt; 60: out.append(("warning", "High muscle-fatigue index"))
    return out


def status_of(alerts):
    lv = [a[0] for a in alerts]
    return "critical" if "critical" in lv else "warning" if lv else "normal"


def protocol_for(aid):
    s = STATE[aid]
    ex, meds, why = [], list(MEDS), []
    if s["fatigue"] &gt; 60 or s["spo2"] &lt; 94:
        ex.append("Light recovery: 15 min cycle ergometer at 50% HRmax + breathing exercises")
        why.append("High fatigue / low SpO2 -&gt; avoid high-intensity work")
    elif s["hr"] &gt; 100 and s["ex_left"] == 0:
        ex.append("Cooldown: 10 min slow breathing (4-6 breaths/min) + stretching")
    else:
        ex += ["Aerobic: 30 min treadmill (harness) at 65-75% HRmax",
               "Resistive: ARED squats/deadlift 3x10 (bone &amp; muscle loss)"]
    ex.append("Daily: 2x10 min eye-tracking + balance drills (use the Mind Game)")
    if s["hydration"] &lt; 55:
        meds.append({"name": "Oral rehydration solution 500 ml", "time": "now"})
        why.append("Low hydration")
    if s["sleep_h"] &lt; 5 and s["stage"] == "Awake":
        meds.append({"name": "Sleep aid (e.g. melatonin) - flight surgeon approval needed", "time": "bedtime"})
        why.append("Short sleep")
    if s["sys"] &gt; 140:
        meds.append({"name": "BP medication - ONLY per flight surgeon", "time": "consult"})
    return {"exercise": ex, "medication": meds, "why": why or ["Vitals within range"]}


def snapshot(aid):
    s = STATE[aid]; al = alerts_for(s)
    return {"id": aid, **ASTRONAUTS[aid], "vitals": {k: round(v, 1) if isinstance(v, float) else v for k, v in s.items()},
            "alerts": [{"level": l, "msg": m} for l, m in al], "status": status_of(al),
            "cognitive": COG[aid], "env": environment(MODE["value"])}


# ---- pages ----
@app.route("/")
def home(): return render_template("earth.html")
@app.route("/astronaut/&lt;int:aid&gt;")
def astronaut_page(aid): return render_template("astronaut.html", aid=aid)
@app.route("/game/&lt;int:aid&gt;")
def game_page(aid): return render_template("game.html", aid=aid)


# ---- API ----
@app.route("/api/astronauts")
def api_all():
    with LOCK:
        return jsonify({"mode": MODE["value"], "astronauts": [snapshot(a) for a in ASTRONAUTS]})

@app.route("/api/astronaut/&lt;int:aid&gt;")
def api_one(aid):
    with LOCK:
        return jsonify({**snapshot(aid), "history": list(HISTORY[aid]), "protocol": protocol_for(aid)})

@app.route("/api/mode", methods=["POST"])
def api_mode():
    m = request.json.get("mode")
    if m in ("space", "earth"): MODE["value"] = m
    return jsonify(environment(MODE["value"]))

@app.route("/api/game/&lt;int:aid&gt;", methods=["POST"])
def api_game(aid):
    d = request.json; rts = d.get("reaction_ms", []); misses = d.get("misses", 0)
    total = len(rts) + misses
    avg = sum(rts) / len(rts) if rts else 9999
    miss_pct = 100 * misses / total if total else 100
    status = ("Alert" if avg &lt; 500 and miss_pct &lt; 15 else
              "Drowsy / reduced attention" if avg &lt; 800 and miss_pct &lt; 35 else "Impaired - notify flight surgeon")
    COG[aid] = {"status": status, "avg_rt": round(avg), "miss_pct": round(miss_pct), "ts": time.strftime("%H:%M:%S")}
    return jsonify(COG[aid])


if __name__ == "__main__":
    init_state()
    threading.Thread(target=sim_loop, daemon=True).start()
    app.run(debug=False, port=5000)
