#include &lt;Wire.h&gt;
#include &lt;MAX30105.h&gt;
#include "heartRate.h"
#include &lt;Adafruit_BMP3XX.h&gt;
#define SEALEVELPRESSURE_HPA 1013.25
MAX30105 max30102;
Adafruit_BMP3XX bmp;
float heartRate = 0;
float spo2 = 98.0;
long lastBeat = 0;
float healthScore = 100;
float fatigueIndex = 0;
String healthStatus = "GREEN";
void calculateHealth()
{
  healthScore = 100;
  if (spo2 &lt; 95)
    healthScore -= 20;
  if (heartRate &gt; 100)
    healthScore -= 15;
  if (heartRate &lt; 50)
    healthScore -= 15;
  if (healthScore &lt; 0)
    healthScore = 0;
}
void calculateFatigue()
{
  fatigueIndex = 0;
  if (spo2 &lt; 95)
    fatigueIndex += 30;
  if (heartRate &gt; 90)
    fatigueIndex += 20;
  if (heartRate &gt; 110)
    fatigueIndex += 20;
  if (fatigueIndex &gt; 100)
    fatigueIndex = 100;
}
void updateStatus()
{
  if (healthScore &gt;= 80)
    healthStatus = "GREEN";
  else if (healthScore &gt;= 60)
    healthStatus = "YELLOW";
  else
    healthStatus = "RED";
}
void setup()
{
  Serial.begin(115200);
  delay(2000);
  Wire.begin();
  Serial.println("AstroHealth Starting...");
  if (!max30102.begin(Wire))
  {
    Serial.println("MAX30102 Not Found");
    while (1);
  }
  max30102.setup();
  if (!bmp.begin_I2C())
  {
    Serial.println("BMP390 Not Found");
    while (1);
  }
  bmp.setTemperatureOversampling(BMP3_OVERSAMPLING_8X);
  bmp.setPressureOversampling(BMP3_OVERSAMPLING_4X);
  bmp.setIIRFilterCoeff(BMP3_IIR_FILTER_COEFF_3);
  Serial.println("Sensors Ready");
}
void loop()
{
  long irValue = max30102.getIR();
  if (checkForBeat(irValue))
  {
    long delta = millis() - lastBeat;
    lastBeat = millis();
    heartRate = 60.0 / (delta / 1000.0);
  }
  if (!bmp.performReading())
  {
    Serial.println("BMP390 Read Error");
    delay(1000);
    return;
  }
  float temperature = bmp.temperature;
  float pressure =
      bmp.pressure / 100.0;
  float altitude =
      bmp.readAltitude(SEALEVELPRESSURE_HPA);
  calculateHealth();
  calculateFatigue();
  updateStatus();
  Serial.println("{");
  Serial.print("\"hr\":");
  Serial.print(heartRate, 1);
  Serial.println(",");
  Serial.print("\"spo2\":");
  Serial.print(spo2, 1);
  Serial.println(",");
  Serial.print("\"temp\":");
  Serial.print(temperature, 1);
  Serial.println(",");
  Serial.print("\"pressure\":");
  Serial.print(pressure, 1);
  Serial.println(",");
  Serial.print("\"altitude\":");
  Serial.print(altitude, 1);
  Serial.println(",");
  Serial.print("\"health\":");
  Serial.print(healthScore, 1);
  Serial.println(",");
  Serial.print("\"fatigue\":");
  Serial.print(fatigueIndex, 1);
  Serial.println(",");
  Serial.print("\"status\":\"");
  Serial.print(healthStatus);
  Serial.println("\"");
  Serial.println("}");
  Serial.println("--------------------------");
  delay(1000);
}
